+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.Locale;
+import java.util.Set;
+
+/**
+ * Criteria understood by {@link CustomerRepository}.
+ *
+ * @param name     whitespace-separated terms; each must occur in the first or last name,
+ *                 ignoring case and accents. Blank matches everything.
+ * @param statuses accepted statuses; empty accepts every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = name == null ? "" : name;
+        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
+    }
+
+    /** Lower-cases and strips accents. */
+    public static String fold(String s) {
+        return Normalizer.normalize(s, Normalizer.Form.NFD)
+                .replaceAll("\\p{M}+", "")
+                .toLowerCase(Locale.ROOT);
+    }
+
+    boolean matches(Customer c, String foldedFirst, String foldedLast) {
+        if (!statuses.isEmpty() && !statuses.contains(c.status())) {
+            return false;
+        }
+        String folded = fold(name).strip();
+        if (folded.isEmpty()) {
+            return true;
+        }
+        return Arrays.stream(folded.split("\\s+"))
+                .allMatch(t -> foldedFirst.contains(t) || foldedLast.contains(t));
+    }
+}
